function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3500)}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}$('#closeModal').onclick=()=>$('#modal').close();
async function api(path,body,{timeoutMs=45000}={}){
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),timeoutMs);
  try{
    let r;
    try{r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:controller.signal})}
    catch(e){if(e.name==='AbortError')throw Error('The request timed out. Please try again.');throw Error('Could not reach the server. Check your connection and try again.')}
    let d;
    try{d=await r.json()}catch(e){if(e.name==='AbortError')throw Error('The request timed out. Please try again.');throw Error('The server returned an unexpected response. Please try again.')}
    if(!r.ok){const e=Error(d.error||'Request failed. Please try again.');e.status=r.status;throw e}
    return d;
  }finally{clearTimeout(timeout)}
}
async function load({requireUser=false}={}){try{const d=await api(`state?season=${season}&week=${week}`,undefined,{timeoutMs:requireUser?15000:45000});if(requireUser&&!d.user)throw Error('Your sign-in could not be confirmed. Please allow cookies for this site and try again.');demo=false;user=d.user;games=d.games;picks=d.picks;saved={...picks};members=d.members||[];standings=d.standings;lastSync=d.lastSync;allSeasons=[...new Set([season,new Date().getFullYear(),...(d.seasons||[])])].sort((a,b)=>b-a);$('#season').innerHTML=allSeasons.map(y=>`<option ${y===season?'selected':''}>${y} season</option>`).join('');$('#connection').textContent='● CONNECTED';$('#connection').style.color='#50815b';$('#profileName').innerHTML=user?`${esc(user.name)}<small>${user.role==='admin'?'League commissioner':'League member'}</small>`:'Sign in<small>Join your friends</small>';document.querySelector('.profile .avatar').textContent=user?initials(user.name):'→'}catch(e){if(requireUser){if(e.status===401)throw Error('Your sign-in could not be confirmed. Please allow cookies for this site and try again.');throw e}if(e.status===401){demo=false;user=null;games=[];picks={};saved={};members=[];standings=[];$('#connection').textContent='● SIGN IN TO PLAY';$('#profileName').innerHTML='Sign in<small>Join your friends</small>'}else if(!demo)toast('Could not refresh. Showing last received data.')}render()}
function initials(n){return n.split(' ').map(x=>x[0]).slice(0,2).join('')}
function activeGames(){return games.filter(g=>g.included)}
function count(){return activeGames().filter(g=>picks[g.id]).length}
function locked(g){return g.status!=='scheduled'||(!demo&&Date.now()>=new Date(g.kickoff).getTime())||(!demo&&new Date(g.kickoff).getFullYear()<new Date().getFullYear())}
function signed(n){return n>0?'+'+n:String(n)}
function heading(title,desc,action=''){return `<div class="heading"><div><div class="eyebrow">COLLEGE FOOTBALL · ${season} SEASON</div><h1>${title}</h1><p class="sub">${desc}</p></div>${action}</div>`}
function rankRows(){if(!demo)return standings;return members.filter(m=>m.active).map((m,i)=>({...m,wins:[48,52,50,46,44,42][i]||0,losses:[24,20,22,26,28,30][i]||0,pushes:0,points:[48,52,50,46,44,42][i]||0})).sort((a,b)=>b.points-a.points)}
function leaders(){return rankRows().slice(0,5).map((p,i)=>`<div class="leader"><span class="rank">${i+1}</span><span class="avatar" style="background:${['#eae7da','#e2e9df','#eadfd5','#e5e6eb','#e8e3dc'][i]}">${esc(initials(p.name))}</span><span class="person">${esc(p.name)}${p.id===user?.id?'<span class="you-tag">YOU</span>':''}<small>${p.wins}–${p.losses}–${p.pushes} record</small></span><strong>${p.points}</strong></div>`).join('')||'<p class="sub">No graded picks yet.</p>'}
function rail(){return `<div class="rail"><section class="rail-card"><div class="rail-title"><h2>The leaderboard</h2><a href="#standings">View all ↗</a></div>${leaders()}<div class="rail-foot">Season points · Updated after final scores</div></section><section class="rail-card"><div class="rail-title"><h2>How we play</h2><span>⚑</span></div><div class="rule-line"><span>Cover the spread</span><b>+1 point</b></div><div class="rule-line"><span>Push (a tie)</span><b>+0.5 points</b></div><div class="rule-line"><span>Miss or no pick</span><b>0 points</b></div><div class="rail-foot">Picks lock at each game’s kickoff.<br>Locked spreads stay the same all week.</div></section><section class="note-card"><div class="eyebrow">COMMISSIONER’S CORNER</div><h3>Good friends. Bad takes.</h3><p>Get your picks in before kickoff. The group chat is a lot more fun when you have a side.</p><a href="#admin">Manage this week ↗</a></section></div>`}
function gameCard(g,scoreMode=false){let selected=picks[g.id];const sp=[-g.spread,g.spread];return `<article class="game"><div class="game-meta"><span class="${g.status==='live'?'live':''}">${g.status==='live'?esc(g.period||'In progress'):g.status==='final'?'FINAL':g.status==='void'?'VOID / POSTPONED':new Date(g.kickoff).toLocaleString('en-US',{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'})}</span><span>${esc(g.network||'NCAA')} ${locked(g)?' · 🔒':''}</span></div><div class="game-body">${['away','home'].map((side,i)=>`${i?'<span class="versus">AT</span>':''}<div class="team ${i?'right':''}"><img class="team-logo" src="https://a.espncdn.com/i/teamlogos/ncaa/500/${g[side+'Id']}.png" alt="" onerror="this.style.visibility='hidden'"><div class="team-text"><b>${g[side+'Rank']?`<sup>${g[side+'Rank']}</sup> `:''}${esc(g[side])}</b><small>${esc(g[side+'Record']||'FBS')} ${scoreMode?'· '+signed(sp[i]):''}</small></div>${g.status!=='scheduled'?`<span class="score">${g[side+'Score']??0}</span>`:''}</div>`).join('')}</div>${!scoreMode?`<div class="pick-row">${['away','home'].map((side,i)=>`<button class="pick ${selected===side?'selected':''}" data-pick="${g.id}:${side}" ${locked(g)||g.spread===null?'disabled':''}><span><i class="circle">${selected===side?'✓':''}</i>${esc(g[side+'Abbr']||g[side])}</span><b>${g.spread===null?'No line':signed(sp[i])}</b></button>`).join('')}</div>`:''}<div class="game-note"><span>${g.status==='final'&&selected?gradeLabel(g,selected):locked(g)?'Picks locked':selected?'✓ '+esc(g[selected])+' selected':'Choose your side'}</span><span>${g.spread===null?'Awaiting spread':g.bookmaker?esc(g.bookmaker)+' · fixed line':'Commissioner’s fixed spread'}</span></div></article>`}
function gradeLabel(g,side){const margin=g.homeScore+g.spread-g.awayScore;return margin===0?'Push · +0.5 points':(side==='home'?margin>0:margin<0)?'Covered · +1 point':'Miss · 0 points'}
function render(){view=location.hash.slice(1)||'picks';if(!['picks','scores','standings','history','admin'].includes(view))view='picks';const titles={picks:'Weekly picks',scores:'Scoreboard',standings:'Standings',history:'Season archive',admin:'Commissioner tools'};$('#breadcrumb').textContent=titles[view];document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===view));$('#pickBadge').textContent=`${count()}/${activeGames().length}`;let html='';const archive=season<2026?`<div class="archive-banner">Viewing the ${season} archive. ${demo?'Sample historical results are shown.':'Archived picks are read-only.'}</div>`:'';
if(view==='picks'){const rows=rankRows(),me=rows.find(p=>p.id===user?.id);html=heading('Every pick. Every Saturday.','A little friendly competition. A whole lot of college football.',`<button class="button" id="weekPicker">▦ &nbsp; Week ${week} &nbsp;⌄</button>`)+archive+`<section class="hero"><div><div class="eyebrow">YOUR SATURDAY STARTS HERE</div><h2>Big games. Bigger bragging rights.</h2><p>Week ${week} is on the clock. Pick your side against the spread.<br><strong>${activeGames().length-count()} picks left.</strong> Trust your gut. Or overthink everything.</p></div><div class="progress-panel"><div class="progress-label"><span>Your weekly picks</span><b>${count()} <span style="font-size:12px;font-weight:400;color:#a8bcae">/ ${activeGames().length}</span></b></div><div class="progress-track"><div style="width:${count()/Math.max(1,activeGames().length)*100}%"></div></div><p>⌁ &nbsp; Each pick locks at its game’s kickoff</p></div></section><div class="stats"><div class="stat"><div class="stat-top"><span>Season rank</span><span>⚑</span></div><strong>${me?'#'+(rows.indexOf(me)+1):'—'} <small> / ${rows.length}</small></strong><small class="positive">The season is still anyone’s game</small></div><div class="stat"><div class="stat-top"><span>Season record</span><span>↗</span></div><strong>${me?me.wins+'–'+me.losses:'0–0'}</strong><small>${me?.pushes||0} pushes this season</small></div><div class="stat"><div class="stat-top"><span>Total points</span><span>✧</span></div><strong>${me?.points||0}<small> pts</small></strong><small>1 cover. 1 point. Simple.</small></div><div class="stat"><div class="stat-top"><span>League members</span><span>♧</span></div><strong>${demo?members.length:rows.length}</strong><small>Your favorite football critics</small></div></div><div class="content-grid"><section><div class="sectionbar"><h2>Week ${week} pick sheet <span style="font:10px 'DM Sans';color:#9ba38f;margin-left:7px">${activeGames().length} GAMES</span></h2><div class="tabs"><button data-tab="all" class="${tab==='all'?'active':''}">All games</button><button data-tab="open" class="${tab==='open'?'active':''}">To pick</button></div></div>${activeGames().filter(g=>tab==='all'||!picks[g.id]&&!locked(g)).map(g=>gameCard(g)).join('')||'<div class="empty">You’re all caught up. See you Saturday.</div>'}<div class="savebar"><span>${JSON.stringify(saved)!==JSON.stringify(picks)?'● You have unsaved picks':'✓ Your saved picks are up to date'}<br>Picks can be changed until kickoff.</span><button class="button primary" id="savePicks">Save my picks &nbsp; ↗</button></div><p class="demo-note">${demo?'Preview league · Sample matchups, scores, spreads, and standings. Picks save on this browser. Connect the included server for shared play and live feeds.':'Spreads freeze when games are added. Scores refresh every 30 seconds while this page is open.'}</p></section>${rail()}</div>`}
if(view==='scores')html=heading('Saturday, in motion.','Follow every drive. See how your picks are holding up.',`<button class="button" id="refresh">↻ Refresh scores</button>`)+archive+`<div class="sectionbar"><h2>Week ${week} scoreboard</h2><span class="eyebrow">${demo?'SAMPLE SCORES':lastSync?'UPDATED '+new Date(lastSync).toLocaleTimeString():'AWAITING FEED SYNC'}</span></div><div class="content-grid"><div>${activeGames().map(g=>gameCard(g,true)).join('')||'<div class="empty">No games selected for this week.</div>'}</div>${rail()}</div>`;
if(view==='standings')html=heading('The bragging rights board.','Every cover counts. Every Saturday matters.',`<button class="button" id="export">↓ Export standings</button>`)+archive+`<div class="sectionbar"><h2>${season} season standings</h2><span class="eyebrow">${demo?'SAMPLE LEAGUE':'FINAL SCORES ONLY'}</span></div><table><thead><tr><th>Rank</th><th>Member</th><th>W–L–P</th><th>Cover %</th><th>Points</th></tr></thead><tbody>${rankRows().map((p,i)=>`<tr class="${p.id===user?.id?'me':''}"><td>${(i&&rankRows()[i-1].points===p.points?rankRows().findIndex(x=>x.points===p.points)+1:i+1)}</td><td><span class="avatar" style="margin-right:10px">${esc(initials(p.name))}</span>${esc(p.name)}${p.id===user?.id?' <span class="you-tag">YOU</span>':''}</td><td>${p.wins}–${p.losses}–${p.pushes}</td><td>${p.wins+p.losses?Math.round(p.wins/(p.wins+p.losses)*100):0}%</td><td><b>${p.points}</b></td></tr>`).join('')}</tbody></table><p class="demo-note">Tied points share a rank. Pushes count as half a point; postponed or canceled games are void.</p>`;
if(view==='history')html=heading('Seasons end. Stories don’t.','A home for every season, every rivalry, and every questionable pick.')+`<div class="history-cards">${allSeasons.map((s,i)=>`<article class="history-card"><div class="eyebrow">${i?'ARCHIVED SEASON':'CURRENT SEASON'}</div><h3>${s} season</h3><p>${demo?(i?'Sample champion · '+['','Sarah Wilson','Matt Carter'][i]:'The race for the top is on.'):'Browse saved picks and final results.'}</p><button class="button" data-year="${s}">View season ↗</button></article>`).join('')}</div><p class="demo-note">${demo?'Archive cards use sample history in the preview.':'All competitions are retained by season and week in the database.'}</p>`;
if(view==='admin')html=renderAdmin();if(!demo&&!user)html=heading('Your crew. Your Saturday.','Sign in to make your picks and follow your league.')+'<div class="admin-panel"><h2>Welcome to Saturday Club</h2><p>Use your account or register with an invite code from the commissioner.</p><button class="button primary" id="signin">Sign in / Join the league</button></div>';$('#app').innerHTML=html;bind();}
function renderAdmin(){if(!demo&&user?.role!=='admin')return heading('Commissioner tools','An admin account is required to manage the league.')+'<button class="button primary" id="signin">Sign in</button>';return heading('Behind the Saturday magic.','Manage the crew, set the slate, and keep the season running.')+`<div class="admin-panel"><div class="sectionbar"><h2>Week ${week} · Game selection</h2><button class="button" id="sync">↻ Sync public feeds</button></div><p>${demo?'Demo controls change this browser’s sample league.':'Sync ESPN score data and spreads; configure ODDS_API_KEY for The Odds API as an additional betting feed.'} Lines are frozen when selected. Games that have started cannot be removed or edited.</p>${games.map(g=>`<div class="admin-game"><label><input type="checkbox" data-include="${g.id}" ${g.included?'checked':''} ${locked(g)?'disabled':''}> ${esc(g.away)} @ ${esc(g.home)}</label><button class="button" data-result="${g.id}">Set result</button><span>Home line <input type="number" step="0.5" data-spread="${g.id}" value="${g.spread??''}" style="width:77px" ${g.included||locked(g)?'disabled':''}></span></div>`).join('')||'<p>No feed games yet. Sync the feed or add a game manually.</p>'}<button class="button primary" id="saveSlate" style="margin-top:18px">Save weekly slate</button></div><div class="admin-panel"><h2>League members</h2><p>Invite friends with a single-use registration code. Disabling a member revokes access while preserving their picks.</p>${members.map(m=>`<div class="admin-game"><span>${esc(m.name)} <small>· ${esc(m.role)}</small></span><button class="button" data-member="${m.id}" ${m.id===user?.id?'disabled':''}>${m.active?'Disable':'Enable'}</button></div>`).join('')}<div class="form-row"><label class="field">Friend’s name<input id="inviteName" placeholder="e.g. Taylor Morgan" maxlength="80"></label><button class="button primary" id="invite">Create invite</button></div><div id="inviteResult"></div></div><div class="admin-panel"><h2>Add a game manually</h2><p>Use this when a public feed does not provide a matchup or spread. Home spread is negative when the home team is favored.</p><div class="form-row"><label class="field">Away team<input id="away"></label><label class="field">Home team<input id="home"></label><label class="field">Home spread<input id="line" type="number" step="0.5"></label><label class="field">Kickoff (your local time)<input id="kickoff" type="datetime-local"></label></div><button class="button" id="addGame">Add game</button></div><div class="admin-panel"><h2>Season & week</h2><p>Each season keeps an independent pick history and standings. Choose the active season and week above to manage its slate.</p><div class="form-row"><label class="field">Season year<input id="seasonYear" type="number" min="2000" max="2100" value="${season}"></label><button class="button" id="openSeason">Open season</button><button class="button" id="weekPicker">Select week ${week} ⌄</button></div></div>`}
function bind(){
$('#openSeason')?.addEventListener('click',()=>{const year=+$('#seasonYear').value;if(year<2000||year>2100||!Number.isInteger(year))return toast('Enter a year between 2000 and 2100.');season=year;if(!Array.from($('#season').options).some(o=>parseInt(o.value)===year)){const opt=document.createElement('option');opt.value=year+' season';opt.textContent=year+' season';$('#season').append(opt)}$('#season').value=year+' season';if(!demo)load();else{games=[];picks={};saved={};render()}});
document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const g=games.find(g=>g.id===b.dataset.result);modal(`<h2>Set game result</h2><p>${esc(g.away)} @ ${esc(g.home)}. Manual results override the current score. The next public feed sync may replace them for feed-backed games.</p><div class="form-row"><label class="field">Away score<input id="awayResult" type="number" min="0" max="200" value="${g.awayScore??0}"></label><label class="field">Home score<input id="homeResult" type="number" min="0" max="200" value="${g.homeScore??0}"></label></div><label class="field">Status<select id="resultStatus"><option value="final">Final</option><option value="void">Void / Canceled</option></select></label><br><button class="button primary" id="saveResult">Save result & grade picks</button>`);$('#saveResult').onclick=async()=>{try{const body={season,week,id:g.id,awayScore:+$('#awayResult').value,homeScore:+$('#homeResult').value,status:$('#resultStatus').value};if(demo){Object.assign(g,body);localStorage.setItem('sc-games',JSON.stringify(games));render()}else{await api('admin/result',body);await load()}$('#modal').close();toast('Result saved. Standings updated.')}catch(e){toast(e.message)}}});
document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const[id,side]=b.dataset.pick.split(':');picks[id]=side;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#savePicks')?.addEventListener('click',async()=>{try{if(demo)localStorage.setItem('sc-picks',JSON.stringify(picks));else{if(!user)return accountModal();await api('picks',{season,week,picks})}saved={...picks};render();toast('Your picks are saved. Bring on Saturday.')}catch(e){toast(e.message)}});$('#weekPicker')?.addEventListener('click',()=>{modal(`<h2>Choose your week</h2><p>View picks and games for each week of ${season}.</p><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">${Array.from({length:18},(_,i)=>`<button class="button" data-week="${i+1}">Week ${i+1}</button>`).join('')}</div>`);document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{week=+b.dataset.week;$('#modal').close();if(demo){games=week===12?JSON.parse(localStorage.getItem('sc-games')||'null')||seedGames:[];picks=week===12?JSON.parse(localStorage.getItem('sc-picks')||'{}'):{};saved={...picks};render()}else load()})});$('#refresh')?.addEventListener('click',()=>{if(demo)toast('Sample scores shown. Live scores require the included backend.');else load()});$('#export')?.addEventListener('click',()=>{const csv=['Rank,Name,Wins,Losses,Pushes,Points',...rankRows().map((p,i)=>`${i+1},"${p.name.replace(/"/g,'""')}",${p.wins},${p.losses},${p.pushes},${p.points}`)].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`saturday-club-${season}.csv`;a.click();URL.revokeObjectURL(a.href)});document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{season=+b.dataset.year;$('#season').value=season+' season';location.hash='standings';if(!demo)load();else render()});$('#sync')?.addEventListener('click',async e=>{if(demo)return toast('Live feed sync is available with the AWS backend.');e.target.disabled=true;e.target.textContent='Syncing…';try{const d=await api('admin/sync',{season,week});toast(d.message);await load()}catch(e){toast(e.message)}finally{render()}});$('#saveSlate')?.addEventListener('click',async()=>{try{const slate=games.map(g=>({...g,included:$(`[data-include="${g.id}"]`).checked,spread:$(`[data-spread="${g.id}"]`).value===''?null:+$(`[data-spread="${g.id}"]`).value}));if(demo){games=slate;localStorage.setItem('sc-games',JSON.stringify(games))}else await api('admin/slate',{season,week,games:slate});toast('Weekly slate saved.');if(!demo)await load();else render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-member]').forEach(b=>b.onclick=async()=>{try{const m=members.find(m=>m.id===b.dataset.member);if(demo){m.active=!m.active;localStorage.setItem('sc-members',JSON.stringify(members));render()}else{await api('admin/member',{id:m.id,active:!m.active});await load()}toast('Member access updated.')}catch(e){toast(e.message)}});$('#invite')?.addEventListener('click',async()=>{const name=$('#inviteName').value.trim();if(!name)return toast('Enter your friend’s name.');try{if(demo){members.push({id:crypto.randomUUID(),name,active:true,role:'member'});localStorage.setItem('sc-members',JSON.stringify(members));render();toast('Sample member added. Real invite codes require the backend.')}else{const d=await api('admin/invite',{name});$('#inviteResult').textContent='Single-use invite code: '+d.code+' · Share this code with '+name+'. They can register from Sign in.'}}catch(e){toast(e.message)}});$('#addGame')?.addEventListener('click',async()=>{try{const g={id:crypto.randomUUID(),away:$('#away').value.trim(),home:$('#home').value.trim(),spread:$('#line').value===''?null:+$('#line').value,kickoff:$('#kickoff').value?new Date($('#kickoff').value).toISOString():null,status:'scheduled',included:false,awayAbbr:$('#away').value.slice(0,4).toUpperCase(),homeAbbr:$('#home').value.slice(0,4).toUpperCase()};if(!g.away||!g.home||g.spread===null||!g.kickoff)return toast('Complete all game fields.');if(demo){games.push(g);localStorage.setItem('sc-games',JSON.stringify(games));render()}else{await api('admin/game',{season,week,game:g});await load()}toast('Game added. Select it to include it in the slate.')}catch(e){toast(e.message)}});$('#signin')?.addEventListener('click',accountModal)}
function accountModal(){
  if(user&&!demo){
    modal(`<h2>${esc(user.name)}</h2><p>You’re signed in as a ${esc(user.role)}.</p><button class="button" id="logout">Sign out</button>`);
    $('#logout').onclick=async()=>{await api('logout',{});$('#modal').close();await load()};return;
  }
  modal(`<h2>${demo?'Welcome to the Club.':'Sign in to Saturday Club.'}</h2><p>${demo?'This hosted preview uses sample data. Shared accounts are available when you run the included AWS backend.':'Sign in with your league account, or enter an invite code to create one.'}</p>${!demo?`<form id="loginForm"><label class="field">Email<input name="email" type="email" autocomplete="username" required></label><br><label class="field">Password<input name="password" type="password" autocomplete="current-password" minlength="10" required></label><br><label class="field">Invite code (new members only)<input name="code" autocomplete="off"></label><div id="loginError" class="form-error" role="alert" tabindex="-1" hidden></div><div class="form-actions"><button type="submit" class="button primary" id="loginSubmit">Sign in</button></div><p id="loginStatus" class="form-status" role="status" aria-live="polite"></p></form>`:'<button class="button primary" id="demoContinue">Explore the demo</button>'}`);
  $('#demoContinue')?.addEventListener('click',()=>$('#modal').close());
  const form=$('#loginForm');
  if(demo||!form)return;
  let submitting=false;
  const button=$('#loginSubmit'),errorBox=$('#loginError'),status=$('#loginStatus');
  const label=()=>form.elements.code.value.trim()?'Create account':'Sign in';
  form.elements.code.addEventListener('input',()=>{if(!submitting)button.textContent=label()});
  form.addEventListener('submit',async event=>{
    event.preventDefault();
    if(submitting)return;
    submitting=true;button.disabled=true;form.setAttribute('aria-busy','true');
    errorBox.hidden=true;errorBox.textContent='';
    const data=Object.fromEntries(new FormData(form));
    data.email=data.email.trim();data.code=data.code.trim();
    button.textContent=data.code?'Creating account…':'Signing in…';status.textContent=button.textContent;
    try{
      await api(data.code?'register':'login',data,{timeoutMs:15000});
      status.textContent='Opening your league…';
      await load({requireUser:true});
      $('#modal').close();
      toast('You’re signed in. Welcome to the Club.');
    }catch(error){
      errorBox.textContent=error.message;errorBox.hidden=false;status.textContent='';errorBox.focus();
    }finally{
      submitting=false;button.disabled=false;button.textContent=label();form.removeAttribute('aria-busy');
    }
  });
}
$('#account').onclick=accountModal;$('#rules').onclick=()=>modal('<h2>A simple game. A long season.</h2><p>Choose either team against the commissioner’s fixed point spread. Cover: 1 point. Push: 0.5 points. Miss or no pick: 0 points.</p><p>Each game locks at kickoff. Spreads freeze when the commissioner includes the game in the weekly slate. Canceled games are void. Final scores determine standings; tied point totals share a rank.</p>');$('#season').onchange=()=>{season=parseInt($('#season').value);if(demo)render();else load()};window.onhashchange=render;render();load();setInterval(()=>{if(!demo&&JSON.stringify(saved)===JSON.stringify(picks))load()},30000);
